/** Waits uninterruptibly for {@code newValue} to be loaded, and then records loading stats. */
@CanIgnoreReturnValue
V getAndRecordStats(
    K key,
    int hash,
    LoadingValueReference<K, V> loadingValueReference,
    ListenableFuture<V> newValue)
    throws ExecutionException {
  V value = null;
  try {
    value = getUninterruptibly(newValue);
    if (value == null) {
      throw new InvalidCacheLoadException("CacheLoader returned null for key " + key + ".");
    }
    statsCounter.recordLoadSuccess(loadingValueReference.elapsedNanos());
    storeLoadedValue(key, hash, loadingValueReference, value);
    return value;
  } finally {
    if (value == null) {
      statsCounter.recordLoadException(loadingValueReference.elapsedNanos());
      removeLoadingValue(key, hash, loadingValueReference);
    }
  }
}

V scheduleRefresh(
    ReferenceEntry<K, V> entry,
    K key,
    int hash,
    V oldValue,
    long now,
    @Nullable CacheLoader<? super K, V> loader) {
  if (map.refreshes()
      && (now - entry.getWriteTime() > map.refreshNanos)
      && !entry.getValueReference().isLoading()) {
    // Since refreshes() is set, checkNonLoadingCache() would've thrown for a non-loading cache.
    requireNonNull(loader);
    V newValue = refresh(key, hash, loader, true);
    if (newValue != null) {
      return newValue;
    }
  }
  return oldValue;
}

/**
 * Refreshes the value associated with {@code key}, unless another thread is already doing so.
 * Returns the newly refreshed value associated with {@code key} if it was refreshed inline, or
 * {@code null} if another thread is performing the refresh or if an error occurs during
 * refresh.
 */
@CanIgnoreReturnValue
@Nullable V refresh(K key, int hash, CacheLoader<? super K, V> loader, boolean checkTime) {
  LoadingValueReference<K, V> loadingValueReference =
      insertLoadingValueReference(key, hash, checkTime);
  if (loadingValueReference == null) {
    return null;
  }

  ListenableFuture<V> result = loadAsync(key, hash, loadingValueReference, loader);
  if (result.isDone()) {
    try {
      return getUninterruptibly(result);
    } catch (Throwable t) {
      // don't let refresh exceptions propagate; error was already logged
    }
  }
  return null;
}

/**
 * Returns a newly inserted {@code LoadingValueReference}, or null if the live value reference
 * is already loading.
 */
@Nullable LoadingValueReference<K, V> insertLoadingValueReference(
    K key, int hash, boolean checkTime) {
  ReferenceEntry<K, V> e;
  lock();
  try {
    long now = map.ticker.read();
    preWriteCleanup(now);

    AtomicReferenceArray<ReferenceEntry<K, V>> table = this.table;
    int index = hash & (table.length() - 1);
    ReferenceEntry<K, V> first = table.get(index);

    // Look for an existing entry.
    for (e = first; e != null; e = e.getNext()) {
      K entryKey = e.getKey();
      if (e.getHash() == hash
          && entryKey != null
          && map.keyEquivalence.equivalent(key, entryKey)) {
        // We found an existing entry.

        ValueReference<K, V> valueReference = e.getValueReference();
        if (valueReference.isLoading()
            || (checkTime && (now - e.getWriteTime() < map.refreshNanos))) {
          // refresh is a no-op if loading is pending
          // if checkTime, we want to check *after* acquiring the lock if refresh still needs
          // to be scheduled
          return null;
        }

        // continue returning old value while loading
        ++modCount;
        LoadingValueReference<K, V> loadingValueReference =
            new LoadingValueReference<>(valueReference);
        e.setValueReference(loadingValueReference);
        return loadingValueReference;
      }
    }

    ++modCount;
    LoadingValueReference<K, V> loadingValueReference = new LoadingValueReference<>();
    e = newEntry(key, hash, first);
    e.setValueReference(loadingValueReference);
    table.set(index, e);
    return loadingValueReference;
  } finally {
    unlock();
    postWriteCleanup();
  }
}

